import{_ as t,a as o,o as a,a4 as r}from"./chunks/framework.-FZumj2l.js";const u=JSON.parse('{"title":"Shop Workflows","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/workflows/shop/index.md","filePath":"api/workflows/shop/index.md","lastUpdated":1783420618000}'),s={name:"api/workflows/shop/index.md"};function n(d,e,i,l,h,c){return a(),o("div",null,e[0]||(e[0]=[r('<h1 id="shop-workflows" tabindex="-1">Shop Workflows <a class="header-anchor" href="#shop-workflows" aria-label="Permalink to &quot;Shop Workflows&quot;">​</a></h1><p>The storefront call-sequences — how a client chains the Shop API (<code>/api/shop/*</code> REST + <code>/api/graphql</code>) to build a customer-facing store. Every request carries the <code>X-STOREFRONT-KEY</code>; customer-scoped steps add <code>Authorization: Bearer &lt;token&gt;</code>.</p><h2 id="agent-ask-inputs" tabindex="-1">Agent-ask inputs <a class="header-anchor" href="#agent-ask-inputs" aria-label="Permalink to &quot;Agent-ask inputs&quot;">​</a></h2><ul><li><strong>Storefront key</strong> — ask the user; send it on every Shop request. Never invent it.</li><li><strong>Server URL</strong> — ask the user for their Bagisto server&#39;s base URL (e.g. <code>https://store.example.com</code>) and prefix every endpoint path with it. Never assume localhost or a demo domain.</li></ul><h2 id="start-here" tabindex="-1">Start here <a class="header-anchor" href="#start-here" aria-label="Permalink to &quot;Start here&quot;">​</a></h2><ul><li><strong><a href="/api/workflows/shop/build-a-storefront.html">Build a Storefront</a></strong> — the complete blueprint: every screen (homepage, catalog, product detail, CMS, themes, account) mapped to its API. Read this first for the whole picture, then drill into a focused flow below.</li></ul><h2 id="focused-flows" tabindex="-1">Focused flows <a class="header-anchor" href="#focused-flows" aria-label="Permalink to &quot;Focused flows&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Workflow</th><th>What it covers</th></tr></thead><tbody><tr><td><a href="/api/workflows/shop/cart.html">Cart</a></td><td>Guest vs customer cart, add/update items, coupons, <strong>merge on login</strong></td></tr><tr><td><a href="/api/workflows/shop/checkout.html">Checkout</a></td><td>Addresses → shipping → payment methods → place order, with saved-address reuse</td></tr></tbody></table><h2 id="guest-vs-customer" tabindex="-1">Guest vs customer <a class="header-anchor" href="#guest-vs-customer" aria-label="Permalink to &quot;Guest vs customer&quot;">​</a></h2><p>The storefront key alone gives read-only access. A <strong>guest can still place an order</strong>: create a Cart Token (<code>createCartToken</code>), send it as <code>Authorization: Bearer &lt;cartToken&gt;</code>, and drive cart + checkout without a login. A logged-in customer additionally unlocks the account area (orders, addresses, wishlist) and lets a guest cart be <strong>merged</strong> into their cart at login.</p><h2 id="how-to-read-a-flow-page" tabindex="-1">How to read a flow page <a class="header-anchor" href="#how-to-read-a-flow-page" aria-label="Permalink to &quot;How to read a flow page&quot;">​</a></h2><p>Intent → Agent-ask inputs → Prerequisites → <strong>Mermaid dependency diagram</strong> → ordered call table (links to the exact endpoint pages) → end-to-end example → customize hook. Flow pages own the sequence; endpoint detail lives on the linked API pages.</p>',12)]))}const f=t(s,[["render",n]]);export{u as __pageData,f as default};
